window.VOL8_TESTS[4]={"id": 4, "module": "listening", "vol": 8, "sections": [{"number": 1, "html": "<p class=\"subheading\"><b>Questions 1–10</b></p><p class=\"instruction\">Complete the form below.</p><p class=\"instruction\">Write <b>ONE WORD AND/OR A NUMBER </b>for each answer.</p><p class=\"\"><b>AA Property Rentals</b></p><p class=\"\">Where property required             Birmingham</p><p class=\"\"><b>Personal details</b></p><p>Name                   Kevin Walker<br>Address                <span class=\"qnum\">1</span><input class=\"gap\" data-q=\"1\" aria-label=\"Câu 1\" autocomplete=\"off\" spellcheck=\"false\">  Road, West Bromwich<br>Phone                   <span class=\"qnum\">2</span><input class=\"gap\" data-q=\"2\" aria-label=\"Câu 2\" autocomplete=\"off\" spellcheck=\"false\">  <br>Occupation           <span class=\"qnum\">3</span><input class=\"gap\" data-q=\"3\" aria-label=\"Câu 3\" autocomplete=\"off\" spellcheck=\"false\"></p><p><b>Details of property wanted<br></b>A two-bedroom    <span class=\"qnum\">4</span><input class=\"gap\" data-q=\"4\" aria-label=\"Câu 4\" autocomplete=\"off\" spellcheck=\"false\"> apartment to rent</p><p class=\"\">Maximum rent     £650 a month</p><p>The bedrooms must be   <span class=\"qnum\">5</span><input class=\"gap\" data-q=\"5\" aria-label=\"Câu 5\" autocomplete=\"off\" spellcheck=\"false\"><br>Date required     <span class=\"qnum\">6</span><input class=\"gap\" data-q=\"6\" aria-label=\"Câu 6\" autocomplete=\"off\" spellcheck=\"false\"></p><p>If possible, the apartment should:<br>• have a  <span class=\"qnum\">7</span><input class=\"gap\" data-q=\"7\" aria-label=\"Câu 7\" autocomplete=\"off\" spellcheck=\"false\"> or a  <span class=\"qnum\">8</span><input class=\"gap\" data-q=\"8\" aria-label=\"Câu 8\" autocomplete=\"off\" spellcheck=\"false\"><br>• be near a  <span class=\"qnum\">9</span><input class=\"gap\" data-q=\"9\" aria-label=\"Câu 9\" autocomplete=\"off\" spellcheck=\"false\"><br>• have a large  <span class=\"qnum\">10</span><input class=\"gap\" data-q=\"10\" aria-label=\"Câu 10\" autocomplete=\"off\" spellcheck=\"false\"></p>"}, {"number": 2, "html": "<p class=\"subheading\"><b>Questions 11–16</b></p><p class=\"instruction\">Choose the correct answer.</p><p class=\"\"><b>Storm Clean-up</b></p><div data-render-choice=\"11\"></div><div data-render-choice=\"12\"></div><div data-render-choice=\"13\"></div><div data-render-choice=\"14\"></div><div data-render-choice=\"15\"></div><div data-render-choice=\"16\"></div>\n<p class=\"subheading\"><b>Questions 17–20</b></p><p class=\"instruction\">What comment does the speaker make about each of the following place?</p><p class=\"instruction\">Choose FOUR correct answers, <b>A-F</b>, next to questions <b>17-20</b>.</p><p class=\"instruction\"><b>Comments</b></p><div class=\"bank\"><button class=\"token\" draggable=\"true\" data-token=\"A\"><b>A</b> It can&#x27;t be reached by car.</button><button class=\"token\" draggable=\"true\" data-token=\"B\"><b>B</b> Repairs are now finished.</button><button class=\"token\" draggable=\"true\" data-token=\"C\"><b>C</b> Planned work has been cancelled.</button><button class=\"token\" draggable=\"true\" data-token=\"D\"><b>D</b> Help is needed to move furniture.</button><button class=\"token\" draggable=\"true\" data-token=\"E\"><b>E</b> New equipment will be bought.</button><button class=\"token\" draggable=\"true\" data-token=\"F\"><b>F</b> Part of the building is damaged.</button></div><p class=\"matching-row\" data-drop=\"17\"><span class=\"qnum\">17</span>The school <select class=\"answer-select\" data-q=\"17\" aria-label=\"Câu 17\"><option value=\"\">Chọn</option><option value=\"A\">A · It can&#x27;t be reached by car.</option><option value=\"B\">B · Repairs are now finished.</option><option value=\"C\">C · Planned work has been cancelled.</option><option value=\"D\">D · Help is needed to move furniture.</option><option value=\"E\">E · New equipment will be bought.</option><option value=\"F\">F · Part of the building is damaged.</option></select></p><p class=\"matching-row\" data-drop=\"18\"><span class=\"qnum\">18</span>The hospital <select class=\"answer-select\" data-q=\"18\" aria-label=\"Câu 18\"><option value=\"\">Chọn</option><option value=\"A\">A · It can&#x27;t be reached by car.</option><option value=\"B\">B · Repairs are now finished.</option><option value=\"C\">C · Planned work has been cancelled.</option><option value=\"D\">D · Help is needed to move furniture.</option><option value=\"E\">E · New equipment will be bought.</option><option value=\"F\">F · Part of the building is damaged.</option></select></p><p class=\"matching-row\" data-drop=\"19\"><span class=\"qnum\">19</span>The High Street <select class=\"answer-select\" data-q=\"19\" aria-label=\"Câu 19\"><option value=\"\">Chọn</option><option value=\"A\">A · It can&#x27;t be reached by car.</option><option value=\"B\">B · Repairs are now finished.</option><option value=\"C\">C · Planned work has been cancelled.</option><option value=\"D\">D · Help is needed to move furniture.</option><option value=\"E\">E · New equipment will be bought.</option><option value=\"F\">F · Part of the building is damaged.</option></select></p><p class=\"matching-row\" data-drop=\"20\"><span class=\"qnum\">20</span>The bikeway <select class=\"answer-select\" data-q=\"20\" aria-label=\"Câu 20\"><option value=\"\">Chọn</option><option value=\"A\">A · It can&#x27;t be reached by car.</option><option value=\"B\">B · Repairs are now finished.</option><option value=\"C\">C · Planned work has been cancelled.</option><option value=\"D\">D · Help is needed to move furniture.</option><option value=\"E\">E · New equipment will be bought.</option><option value=\"F\">F · Part of the building is damaged.</option></select></p>"}, {"number": 3, "html": "<p class=\"subheading\"><b>Questions 21–30</b></p><p class=\"instruction\">Complete the notes below.</p><p class=\"instruction\">Write N<b>O MORE THAN THREE WORDS AND/OR A NUMBER</b> for each answer.</p><p class=\"\"><b>Possible Course Change</b></p><p class=\"\">Name of student:  Sally Layman</p><p>Current course: <span class=\"qnum\">21</span><input class=\"gap\" data-q=\"21\" aria-label=\"Câu 21\" autocomplete=\"off\" spellcheck=\"false\"></p><p>Date started:               <span class=\"qnum\">22</span><input class=\"gap\" data-q=\"22\" aria-label=\"Câu 22\" autocomplete=\"off\" spellcheck=\"false\"></p><p>Courses interested in: 1st choice  <span class=\"qnum\">23</span><input class=\"gap\" data-q=\"23\" aria-label=\"Câu 23\" autocomplete=\"off\" spellcheck=\"false\"></p><p>2nd choice  <span class=\"qnum\">24</span><input class=\"gap\" data-q=\"24\" aria-label=\"Câu 24\" autocomplete=\"off\" spellcheck=\"false\"></p><div class=\"table-scroll\"><table class=\"source-table\"><tr><td><p class=\"\"><b>Problem</b></p></td><td><p class=\"\"><b>Strategies tried</b></p></td><td><p class=\"\"><b>Further strategies suggested</b></p></td></tr><tr><td><p class=\"\">finds</p><p><span class=\"qnum\">25</span><input class=\"gap\" data-q=\"25\" aria-label=\"Câu 25\" autocomplete=\"off\" spellcheck=\"false\"></p></td><td><p class=\"\">recording them</p></td><td><p class=\"\">join other students in a</p><p><span class=\"qnum\">26</span><input class=\"gap\" data-q=\"26\" aria-label=\"Câu 26\" autocomplete=\"off\" spellcheck=\"false\"></p></td></tr><tr><td><p><span class=\"qnum\">27</span><input class=\"gap\" data-q=\"27\" aria-label=\"Câu 27\" autocomplete=\"off\" spellcheck=\"false\"></p></td><td><p class=\"\">talking to tutor</p></td><td><p class=\"\">arrange meetings in advance</p></td></tr><tr><td><p class=\"\">bad assignment</p></td><td><p class=\"\">more background reading</p></td><td><p>visit <span class=\"qnum\">28</span><input class=\"gap\" data-q=\"28\" aria-label=\"Câu 28\" autocomplete=\"off\" spellcheck=\"false\"></p></td></tr></table></div><p>Date for next meeting:  <span class=\"qnum\">29</span><input class=\"gap\" data-q=\"29\" aria-label=\"Câu 29\" autocomplete=\"off\" spellcheck=\"false\">   at 3.30 p. m.</p><p>With:  <span class=\"qnum\">30</span><input class=\"gap\" data-q=\"30\" aria-label=\"Câu 30\" autocomplete=\"off\" spellcheck=\"false\"></p>"}, {"number": 4, "html": "<p class=\"subheading\"><b>Questions 31–40</b></p><p class=\"instruction\"><i>Choose the correct answer.</i></p><p class=\"\"><b>Perfume Ornaments</b></p><div data-render-choice=\"31\"></div><div data-render-choice=\"32\"></div><div data-render-choice=\"33\"></div><div data-render-choice=\"34\"></div><div data-render-choice=\"35\"></div><div data-render-choice=\"36\"></div><div data-render-choice=\"37\"></div><div data-render-choice=\"38\"></div><div data-render-choice=\"39\"></div><div data-render-choice=\"40\"></div>"}], "passages": [], "singles": [{"n": 11, "prompt": "Compared to last years storm, this year", "options": ["more houses in the area were affected.", "the water levels rose much higher.", "there was more severe damage to trees."]}, {"n": 12, "prompt": "According to the speaker, what should you do if your home has been flooded?", "options": ["switch off the electricity", "try to drain the water", "wait for a few days"]}, {"n": 13, "prompt": "What does the speaker advise residents to do with their garden waste?", "options": ["put it in a special bin", "take it to the council rubbish centre", "pile it next to the road"]}, {"n": 14, "prompt": "People who cannot cook food should", "options": ["pick up vouchers from the council office", "get a meal in the community centre", "arrange for food to be brought to their home"]}, {"n": 15, "prompt": "People who want to help out are asked to", "options": ["contact their local council office", "come to the community centre in the morning", "bring their tools to the council office"]}, {"n": 16, "prompt": "What problem should residents report to the council?", "options": ["an increased number of mosquitoes", "native animals found in unusual places", "contaminated water"]}, {"n": 31, "prompt": "The museum started displaying perfume ornaments when", "options": ["a collection was donated", "the public showed an interest in them", "an expert decided some of them were valuable"]}, {"n": 32, "prompt": "People needed to wear perfume in the 11 century because", "options": ["washing was considered dangerous", "soap was not generally available", "water shortages were common"]}, {"n": 33, "prompt": "The perfume ornament known as a 'pomander took its name from", "options": ["the substance it was made of", "the liquid inside it", "the person who invented it"]}, {"n": 34, "prompt": "In medieval times, it was thought that wearing perfume made people", "options": ["more wealthy", "more attractive", "more cheerful"]}, {"n": 35, "prompt": "Craftsmen found ways of preventing liquid perfume from", "options": ["being spilled", "drying up", "losing its scent."]}, {"n": 36, "prompt": "The perfume in a vinaigrette was", "options": ["preserved in solid form", "absorbed by a sponge", "heated over a flame"]}, {"n": 37, "prompt": "Which part of the vinaigrette was made of gold?", "options": ["the inside", "the outside", "the lid"]}, {"n": 38, "prompt": "Perfume bottles used in the mid- 19\"century", "options": ["were imports from outside Europe", "could be bought by large numbers of people", "were usually made of horn"]}, {"n": 39, "prompt": "Tiffany bottles", "options": ["were produced by a number of companies", "could only be bought from catalogues", "showed skilled use of crystal"]}, {"n": 40, "prompt": "The ‘Vanity’ was", "options": ["used for storing cosmetics", "the smallest perfume ornament ever made", "developed in the 1950s"]}], "pairs": [], "answers": {"1": ["354 Forest"], "2": ["07817983602"], "3": ["dentist"], "4": ["unfurnished"], "5": ["doubles"], "6": ["1 November", "1st November", "November 1", "November 1st"], "7": ["balcony"], "8": ["garden"], "9": ["station"], "10": ["kitchen"], "11": ["A"], "12": ["C"], "13": ["C"], "14": ["A"], "15": ["B"], "16": ["B"], "17": ["D"], "18": ["F"], "19": ["A"], "20": ["C"], "21": ["Economic History"], "22": ["last September"], "23": ["Politics"], "24": ["Philosophy"], "25": ["lectures difficult"], "26": ["discussion group"], "27": ["not enough tutorials"], "28": ["student services"], "29": ["17th of February", "17 February", "February 17", "17th February"], "30": ["senior advisor"], "31": ["C"], "32": ["A"], "33": ["A"], "34": ["C"], "35": ["B"], "36": ["B"], "37": ["A"], "38": ["B"], "39": ["C"], "40": ["A"]}, "explanations": {}, "transcriptSegments": {"1": [{"id": "s1-t1", "text": "You will hear a telephone conversation between a man who wants to rent an apartment and an agent at a property rental service. First, you have some time to look at questions 1 to 5. Now listen carefully and answer questions 1 to 5. Good morning, AA Property. Can I help you? Yes, good morning.", "html": "<p>You will hear a telephone conversation between a man who wants to rent an apartment and an agent at a property rental service. First, you have some time to look at questions 1 to 5. Now listen carefully and answer questions 1 to 5. Good morning, AA Property. Can I help you? Yes, good morning.</p>", "start": null}, {"id": "s1-t2", "text": "I'm looking for an apartment to rent. OK. Is that here in Birmingham? That's right.", "html": "<p>I&#x27;m looking for an apartment to rent. OK. Is that here in Birmingham? That&#x27;s right.</p>", "start": null}, {"id": "s1-t3", "text": "Right. I'll just take some personal details if I may. So, if I can just take your name? Kevin Walker.", "html": "<p>Right. I&#x27;ll just take some personal details if I may. So, if I can just take your name? Kevin Walker.</p>", "start": null}, {"id": "s1-t4", "text": "Right. And can I have your present address, please? Well, we're staying with friends at present, so the address is 354 Forest Road. Is that Forest with one R? That's right.", "html": "<p>Right. And can I have your present address, please? Well, we&#x27;re staying with friends at present, so the address is 354 Forest Road. Is that Forest with one R? That&#x27;s right.</p>", "start": null}, {"id": "s1-t5", "text": "And that's in West Bromwich. I'm afraid I don't know the postcode. That's OK.", "html": "<p>And that&#x27;s in West Bromwich. I&#x27;m afraid I don&#x27;t know the postcode. That&#x27;s OK.</p>", "start": null}, {"id": "s1-t6", "text": "And a contact phone number? 07817983602. Lovely. And if I could just ask your occupation? Certainly.", "html": "<p>And a contact phone number? 07817983602. Lovely. And if I could just ask your occupation? Certainly.</p>", "start": null}, {"id": "s1-t7", "text": "I'm a dentist and my wife's a teacher, but she's at home at present looking after the children. OK. So, I'll just put your occupation.", "html": "<p>I&#x27;m a dentist and my wife&#x27;s a teacher, but she&#x27;s at home at present looking after the children. OK. So, I&#x27;ll just put your occupation.</p>", "start": null}, {"id": "s1-t8", "text": "Right. Well, now I'll take some details about the kind of property you're looking for. You said you're looking for an apartment, is that right? Yeah.", "html": "<p>Right. Well, now I&#x27;ll take some details about the kind of property you&#x27;re looking for. You said you&#x27;re looking for an apartment, is that right? Yeah.</p>", "start": null}, {"id": "s1-t9", "text": "OK. So, how many bedrooms do you want? Two. And did you want it furnished? No, unfurnished.", "html": "<p>OK. So, how many bedrooms do you want? Two. And did you want it furnished? No, unfurnished.</p>", "start": null}, {"id": "s1-t10", "text": "Right. Well, that gives you quite a bit more choice, so that's good. And what's the maximum rent you'd be prepared to pay? Well, we'd like to stay under £600 if possible, but we could go up to £650 for the right place.", "html": "<p>Right. Well, that gives you quite a bit more choice, so that&#x27;s good. And what&#x27;s the maximum rent you&#x27;d be prepared to pay? Well, we&#x27;d like to stay under £600 if possible, but we could go up to £650 for the right place.</p>", "start": null}, {"id": "s1-t11", "text": "Right. So, do you have any other definite requirements? Well, coming back to the bedrooms, they have to be doubles, both of them. OK.", "html": "<p>Right. So, do you have any other definite requirements? Well, coming back to the bedrooms, they have to be doubles, both of them. OK.</p>", "start": null}, {"id": "s1-t12", "text": "I'll make a note of that. Before you hear the rest of the conversation, you have some time to look at questions 6 to 10. Now listen and answer questions 6 to 10.", "html": "<p>I&#x27;ll make a note of that. Before you hear the rest of the conversation, you have some time to look at questions 6 to 10. Now listen and answer questions 6 to 10.</p>", "start": null}, {"id": "s1-t13", "text": "So, are you looking for something straight away? I assume you are if you're staying with friends. Well, as soon as possible, yes. Well, it's October 17th today, so we're probably looking at November 1st at the earliest.", "html": "<p>So, are you looking for something straight away? I assume you are if you&#x27;re staying with friends. Well, as soon as possible, yes. Well, it&#x27;s October 17th today, so we&#x27;re probably looking at November 1st at the earliest.</p>", "start": null}, {"id": "s1-t14", "text": "Would that be OK? Well, I'd have preferred something in October, but OK, let's put that date down for now. Fine. Now, is there anything else you'd like? Well, our last flat had a garage, but actually, we never used it, so I'm not really worried about that.", "html": "<p>Would that be OK? Well, I&#x27;d have preferred something in October, but OK, let&#x27;s put that date down for now. Fine. Now, is there anything else you&#x27;d like? Well, our last flat had a garage, but actually, we never used it, so I&#x27;m not really worried about that.</p>", "start": null}, {"id": "s1-t15", "text": "But we'd like a balcony if possible. It's nice not to be too shut in. Yes.", "html": "<p>But we&#x27;d like a balcony if possible. It&#x27;s nice not to be too shut in. Yes.</p>", "start": null}, {"id": "s1-t16", "text": "You'll find most modern apartments do have one. It's only the converted properties that don't. But of course, if you're in an older property, you might have use of a garden.", "html": "<p>You&#x27;ll find most modern apartments do have one. It&#x27;s only the converted properties that don&#x27;t. But of course, if you&#x27;re in an older property, you might have use of a garden.</p>", "start": null}, {"id": "s1-t17", "text": "Would that be a possible alternative? Oh yes, either of those would be good. What about transport? Would you want off-street parking? No, parking doesn't matter, but it'd be good to have somewhere not too far from a station if possible. But it's not essential.", "html": "<p>Would that be a possible alternative? Oh yes, either of those would be good. What about transport? Would you want off-street parking? No, parking doesn&#x27;t matter, but it&#x27;d be good to have somewhere not too far from a station if possible. But it&#x27;s not essential.</p>", "start": null}, {"id": "s1-t18", "text": "I've got a bike. Right. And what else? You'll want a lounge, and will you want a separate dining room? Well, not really.", "html": "<p>I&#x27;ve got a bike. Right. And what else? You&#x27;ll want a lounge, and will you want a separate dining room? Well, not really.</p>", "start": null}, {"id": "s1-t19", "text": "We tend to eat in the kitchen, so it'd be good if that was large enough for us to do that. That might be difficult, but I'll make a note of it anyway. Right, well, let's have a look at what...", "html": "<p>We tend to eat in the kitchen, so it&#x27;d be good if that was large enough for us to do that. That might be difficult, but I&#x27;ll make a note of it anyway. Right, well, let&#x27;s have a look at what...</p>", "start": null}], "2": [{"id": "s2-t1", "text": "Section 2. You will hear a local councillor giving advice on the radio about cleaning up after recent bad weather.", "html": "<p>Section 2. You will hear a local councillor giving advice on the radio about cleaning up after recent bad weather.</p>", "start": null}, {"id": "s2-t2", "text": "First, you have some time to look at questions 11 to 16 on page 3. Now listen carefully and answer questions 11 to 16. Welcome to Radio OK, your community radio station. After our recent bad storm, we have Councillor Phil Evans joining us to tell us about the clean-up effort.", "html": "<p>First, you have some time to look at questions 11 to 16 on page 3. Now listen carefully and answer questions 11 to 16. Welcome to Radio OK, your community radio station. After our recent bad storm, we have Councillor Phil Evans joining us to tell us about the clean-up effort.</p>", "start": null}, {"id": "s2-t3", "text": "Welcome, Phil. Hello. Thanks for having me.", "html": "<p>Welcome, Phil. Hello. Thanks for having me.</p>", "start": null}, {"id": "s2-t4", "text": "Well, we had some pretty severe weather at the weekend. Thankfully, it wasn't quite as bad as last year's storm. Although there was some damage to trees, it was definitely not on the same scale as last year, and we were expecting the river level to rise higher than it did.", "html": "<p>Well, we had some pretty severe weather at the weekend. Thankfully, it wasn&#x27;t quite as bad as last year&#x27;s storm. Although there was some damage to trees, it was definitely not on the same scale as last year, and we were expecting the river level to rise higher than it did.</p>", "start": null}, {"id": "s2-t5", "text": "But having said that, a much larger number of homes have been damaged this year due to flash flooding near the creek. Those of you who have experienced flooding, we ask you to be especially careful. I know it's upsetting to see your home full of water, but please be patient, as there's nothing you can do until the river level drops, hopefully in two or three days.", "html": "<p>But having said that, a much larger number of homes have been damaged this year due to flash flooding near the creek. Those of you who have experienced flooding, we ask you to be especially careful. I know it&#x27;s upsetting to see your home full of water, but please be patient, as there&#x27;s nothing you can do until the river level drops, hopefully in two or three days.</p>", "start": null}, {"id": "s2-t6", "text": "You won't have any electricity at the moment, but we are working as fast as we can to get it reconnected. When it comes to cleaning up your garden, you might be tempted to just throw dead branches and so on into your normal garbage bin. Please don't.", "html": "<p>You won&#x27;t have any electricity at the moment, but we are working as fast as we can to get it reconnected. When it comes to cleaning up your garden, you might be tempted to just throw dead branches and so on into your normal garbage bin. Please don&#x27;t.</p>", "start": null}, {"id": "s2-t7", "text": "We're asking people to simply stack them outside on the footpath ready for Council collection. We plan to cut them up and use them for composting. For those of you who don't have cooking facilities at the moment, I'm afraid we won't be able to deliver hot meals to your home like the community centre did last year.", "html": "<p>We&#x27;re asking people to simply stack them outside on the footpath ready for Council collection. We plan to cut them up and use them for composting. For those of you who don&#x27;t have cooking facilities at the moment, I&#x27;m afraid we won&#x27;t be able to deliver hot meals to your home like the community centre did last year.</p>", "start": null}, {"id": "s2-t8", "text": "Instead, we'll be issuing vouchers that you can use to get food from any of the nominated restaurants. Just come to the Council office to collect them. We've had an overwhelming number of people offering to help out.", "html": "<p>Instead, we&#x27;ll be issuing vouchers that you can use to get food from any of the nominated restaurants. Just come to the Council office to collect them. We&#x27;ve had an overwhelming number of people offering to help out.</p>", "start": null}, {"id": "s2-t9", "text": "Anyone who would like to volunteer, please don't call the Council office directly. Instead, if you're available to help clean up, just turn up at the community centre by 8am tomorrow and you'll be given the necessary tools and assigned a task by the Council Work Supervisor. As the water level goes down, we may discover more problems.", "html": "<p>Anyone who would like to volunteer, please don&#x27;t call the Council office directly. Instead, if you&#x27;re available to help clean up, just turn up at the community centre by 8am tomorrow and you&#x27;ll be given the necessary tools and assigned a task by the Council Work Supervisor. As the water level goes down, we may discover more problems.</p>", "start": null}, {"id": "s2-t10", "text": "We'll be assessing the drinking water regularly so that there's no risk of contamination. Just be aware that local wildlife can be forced out of their natural habitat in this weather. Let the Council know of any unusual sightings so we can safely relocate them.", "html": "<p>We&#x27;ll be assessing the drinking water regularly so that there&#x27;s no risk of contamination. Just be aware that local wildlife can be forced out of their natural habitat in this weather. Let the Council know of any unusual sightings so we can safely relocate them.</p>", "start": null}, {"id": "s2-t11", "text": "It may seem that mosquitoes are around in abundance right now, but the actual population is usual for this time of year. Before you hear the rest of the talk, you have some time to look at questions 17 to 20 on page 4. Now listen and answer questions 17 to 20. Now we'll give you some information about key areas in the town.", "html": "<p>It may seem that mosquitoes are around in abundance right now, but the actual population is usual for this time of year. Before you hear the rest of the talk, you have some time to look at questions 17 to 20 on page 4. Now listen and answer questions 17 to 20. Now we&#x27;ll give you some information about key areas in the town.</p>", "start": null}, {"id": "s2-t12", "text": "The school escaped any real problems and we'll be using its car park and some of the classrooms to coordinate the clean up. Because of that, the Principal is asking for volunteers to assist in getting the classrooms set back up again with the desks back in their proper places before the new term begins after the holidays. The hospital is still fully functional and the only damage there was to the canteen where a tree branch broke a window.", "html": "<p>The school escaped any real problems and we&#x27;ll be using its car park and some of the classrooms to coordinate the clean up. Because of that, the Principal is asking for volunteers to assist in getting the classrooms set back up again with the desks back in their proper places before the new term begins after the holidays. The hospital is still fully functional and the only damage there was to the canteen where a tree branch broke a window.</p>", "start": null}, {"id": "s2-t13", "text": "You can still access the area as normal, we just ask that you park at the rear of the hospital until the repair work has been completed. If you need to get to the shops, the High Street is still a little flooded so I'm afraid you'll have to collect your shopping on foot for a little while. Hopefully, it won't be long before you'll be able to drive there again.", "html": "<p>You can still access the area as normal, we just ask that you park at the rear of the hospital until the repair work has been completed. If you need to get to the shops, the High Street is still a little flooded so I&#x27;m afraid you&#x27;ll have to collect your shopping on foot for a little while. Hopefully, it won&#x27;t be long before you&#x27;ll be able to drive there again.</p>", "start": null}, {"id": "s2-t14", "text": "Before the storm, we had hoped to begin work on modernising the bikeway that runs along the river. We were particularly looking forward to having bike storage facilities installed. While the bikeway itself is okay, unfortunately the area around it is covered in water.", "html": "<p>Before the storm, we had hoped to begin work on modernising the bikeway that runs along the river. We were particularly looking forward to having bike storage facilities installed. While the bikeway itself is okay, unfortunately the area around it is covered in water.</p>", "start": null}, {"id": "s2-t15", "text": "So we've postponed our work there indefinitely and I'm afraid it's now unlikely that this will ever go ahead. Well, that's everything for now. I'll be back with a further update tomorrow.", "html": "<p>So we&#x27;ve postponed our work there indefinitely and I&#x27;m afraid it&#x27;s now unlikely that this will ever go ahead. Well, that&#x27;s everything for now. I&#x27;ll be back with a further update tomorrow.</p>", "start": null}, {"id": "s2-t16", "text": "That is the end of Section 2. You now have half a minute to check your answers.", "html": "<p>That is the end of Section 2. You now have half a minute to check your answers.</p>", "start": null}], "3": [{"id": "s3-t1", "text": "Now turn to Section 3 on page 5. Section 3. You will hear a student talking to a tutor at her college about the possibility of changing her course. First, you have some time to look at questions 21 to 24 on page 5. Now listen carefully and answer questions 21 to 24.", "html": "<p>Now turn to Section 3 on page 5. Section 3. You will hear a student talking to a tutor at her college about the possibility of changing her course. First, you have some time to look at questions 21 to 24 on page 5. Now listen carefully and answer questions 21 to 24.</p>", "start": null}, {"id": "s3-t2", "text": "Ah, hello. Do come in. Thanks.", "html": "<p>Ah, hello. Do come in. Thanks.</p>", "start": null}, {"id": "s3-t3", "text": "I understand you wanted to see me about changing courses? Yes, that's right. Well, that's fine. Do sit down.", "html": "<p>I understand you wanted to see me about changing courses? Yes, that&#x27;s right. Well, that&#x27;s fine. Do sit down.</p>", "start": null}, {"id": "s3-t4", "text": "Oh, thank you. Now, you're Sally Lehman? That's it. Right then, Sally.", "html": "<p>Oh, thank you. Now, you&#x27;re Sally Lehman? That&#x27;s it. Right then, Sally.</p>", "start": null}, {"id": "s3-t5", "text": "And what course are you doing at the present? It's Economic History. Uh-huh. And when did you start? Last September.", "html": "<p>And what course are you doing at the present? It&#x27;s Economic History. Uh-huh. And when did you start? Last September.</p>", "start": null}, {"id": "s3-t6", "text": "Right, good. Now, of course, we'll have the chance to talk through any problems you've been having in a moment, but let me just make a note of what courses you might be interested in changing to. Well, there are several that I've thought about, but what I'd like to do most is politics.", "html": "<p>Right, good. Now, of course, we&#x27;ll have the chance to talk through any problems you&#x27;ve been having in a moment, but let me just make a note of what courses you might be interested in changing to. Well, there are several that I&#x27;ve thought about, but what I&#x27;d like to do most is politics.</p>", "start": null}, {"id": "s3-t7", "text": "Well, that is a very popular course. I know, and there might not be places, but… Sure, I'll certainly take a note of that. But what about another option? Well, I had thought of changing course completely and trying business studies, but then I realised it wasn't really me, so I thought of philosophy.", "html": "<p>Well, that is a very popular course. I know, and there might not be places, but… Sure, I&#x27;ll certainly take a note of that. But what about another option? Well, I had thought of changing course completely and trying business studies, but then I realised it wasn&#x27;t really me, so I thought of philosophy.</p>", "start": null}, {"id": "s3-t8", "text": "Before you hear the rest of the discussion, you have some time to look at questions 25 to 30 on page 5. Now listen and answer questions 25 to 30. Right, well, that's useful to know, but if at all possible, it is good to talk through the problems you are having at the moment and see if there's any way we can help or that you can help yourself. After all, with all the effort that you've put in already, it would be a pity to have to start all over again.", "html": "<p>Before you hear the rest of the discussion, you have some time to look at questions 25 to 30 on page 5. Now listen and answer questions 25 to 30. Right, well, that&#x27;s useful to know, but if at all possible, it is good to talk through the problems you are having at the moment and see if there&#x27;s any way we can help or that you can help yourself. After all, with all the effort that you&#x27;ve put in already, it would be a pity to have to start all over again.</p>", "start": null}, {"id": "s3-t9", "text": "Oh no, I realise that. And actually, I would like to have a go at staying with Economic History. Good.", "html": "<p>Oh no, I realise that. And actually, I would like to have a go at staying with Economic History. Good.</p>", "start": null}, {"id": "s3-t10", "text": "Yeah, well, let's see. Let's talk through some of the problems you've been having. What would you say was your major difficulty on the course? I think I'd have to say the worst thing is that I find the lectures difficult.", "html": "<p>Yeah, well, let&#x27;s see. Let&#x27;s talk through some of the problems you&#x27;ve been having. What would you say was your major difficulty on the course? I think I&#x27;d have to say the worst thing is that I find the lectures difficult.</p>", "start": null}, {"id": "s3-t11", "text": "Aha. And how have you tried to overcome this? Well, I did try recording lectures, you know. Yes, that's a good idea.", "html": "<p>Aha. And how have you tried to overcome this? Well, I did try recording lectures, you know. Yes, that&#x27;s a good idea.</p>", "start": null}, {"id": "s3-t12", "text": "And did you find it helped? To a certain extent, but... Well, I would certainly continue with that strategy, but you might also like to try getting together with other fellow students to discuss lectures in what we call a discussion group. Yeah, I've heard of some of my course mates doing that. I could certainly ask if I could join.", "html": "<p>And did you find it helped? To a certain extent, but... Well, I would certainly continue with that strategy, but you might also like to try getting together with other fellow students to discuss lectures in what we call a discussion group. Yeah, I&#x27;ve heard of some of my course mates doing that. I could certainly ask if I could join.</p>", "start": null}, {"id": "s3-t13", "text": "Good. I'm sure you'd find it a help. And any other problems? Well, this really worried me at the beginning.", "html": "<p>Good. I&#x27;m sure you&#x27;d find it a help. And any other problems? Well, this really worried me at the beginning.</p>", "start": null}, {"id": "s3-t14", "text": "The fact that there are not enough tutorials. Not enough tutorials. Did you talk to your tutor about it? Yeah, that was what I thought was the best strategy.", "html": "<p>The fact that there are not enough tutorials. Not enough tutorials. Did you talk to your tutor about it? Yeah, that was what I thought was the best strategy.</p>", "start": null}, {"id": "s3-t15", "text": "It's what all the student handbooks say. Yeah, and what was the outcome? Well, really, just that she's very busy and I have to fit in tutorials when she's available, which is really difficult. I agree.", "html": "<p>It&#x27;s what all the student handbooks say. Yeah, and what was the outcome? Well, really, just that she&#x27;s very busy and I have to fit in tutorials when she&#x27;s available, which is really difficult. I agree.</p>", "start": null}, {"id": "s3-t16", "text": "It must seem that way. Why don't you try arranging meetings in advance? Well, I can certainly give it a go. Yeah.", "html": "<p>It must seem that way. Why don&#x27;t you try arranging meetings in advance? Well, I can certainly give it a go. Yeah.</p>", "start": null}, {"id": "s3-t17", "text": "But I suppose the thing that's been really upsetting me recently is my bad assignment grade. How many have you had back? Just the one. Well, you could say it was early days yet.", "html": "<p>But I suppose the thing that&#x27;s been really upsetting me recently is my bad assignment grade. How many have you had back? Just the one. Well, you could say it was early days yet.</p>", "start": null}, {"id": "s3-t18", "text": "Well, for the last assignment, which we've just handed in, I did more background reading. And did you feel that helped? Oh, yes, I think so. Well, another strategy might be visiting student services.", "html": "<p>Well, for the last assignment, which we&#x27;ve just handed in, I did more background reading. And did you feel that helped? Oh, yes, I think so. Well, another strategy might be visiting student services.</p>", "start": null}, {"id": "s3-t19", "text": "They offer a lot of advice on assignment preparation. Well, I didn't want to bother them. That's their job.", "html": "<p>They offer a lot of advice on assignment preparation. Well, I didn&#x27;t want to bother them. That&#x27;s their job.</p>", "start": null}, {"id": "s3-t20", "text": "It'd be well worth trying. OK, I'll certainly look into that. Now, what I've done here is to keep a record of our discussions and suggested strategies.", "html": "<p>It&#x27;d be well worth trying. OK, I&#x27;ll certainly look into that. Now, what I&#x27;ve done here is to keep a record of our discussions and suggested strategies.</p>", "start": null}, {"id": "s3-t21", "text": "And what we normally do is to ask you to try out our suggestions for a while and then come back to discuss the situation, see whether it's improved. And if not, then we can start thinking seriously about those alternative courses. So you'd like me to come back? Yes.", "html": "<p>And what we normally do is to ask you to try out our suggestions for a while and then come back to discuss the situation, see whether it&#x27;s improved. And if not, then we can start thinking seriously about those alternative courses. So you&#x27;d like me to come back? Yes.</p>", "start": null}, {"id": "s3-t22", "text": "Let's say in a month's time. OK. That'd be on 17th of February at 3.30. Is that all right? Yeah, sure.", "html": "<p>Let&#x27;s say in a month&#x27;s time. OK. That&#x27;d be on 17th of February at 3.30. Is that all right? Yeah, sure.</p>", "start": null}, {"id": "s3-t23", "text": "And will I meet with you? I'm afraid I'll be on leave at that time. But I'll leave this record on file and you'll be meeting our senior advisor. Senior advisor.", "html": "<p>And will I meet with you? I&#x27;m afraid I&#x27;ll be on leave at that time. But I&#x27;ll leave this record on file and you&#x27;ll be meeting our senior advisor. Senior advisor.</p>", "start": null}, {"id": "s3-t24", "text": "OK, fine. Lovely. Well, I do hope things improve, Sally, and that the change won't be necessary.", "html": "<p>OK, fine. Lovely. Well, I do hope things improve, Sally, and that the change won&#x27;t be necessary.</p>", "start": null}, {"id": "s3-t25", "text": "And if it is, well, we can think about that later. OK? OK. Thanks very much.", "html": "<p>And if it is, well, we can think about that later. OK? OK. Thanks very much.</p>", "start": null}, {"id": "s3-t26", "text": "Pleasure. Good luck. That is the end of Section 3. You now have half a minute to check your answers.", "html": "<p>Pleasure. Good luck. That is the end of Section 3. You now have half a minute to check your answers.</p>", "start": null}], "4": [{"id": "s4-t1", "text": "Now turn to Section 4 on page 6. Section 4. You will hear a museum curator giving a presentation about her museum's collection of perfume containers, also known as perfume ornaments. First, you have some time to look at questions 31 to 40 on pages 6 and 7. Now listen carefully and answer questions 31 to 40. Good morning and welcome to the Walden Gallery.", "html": "<p>Now turn to Section 4 on page 6. Section 4. You will hear a museum curator giving a presentation about her museum&#x27;s collection of perfume containers, also known as perfume ornaments. First, you have some time to look at questions 31 to 40 on pages 6 and 7. Now listen carefully and answer questions 31 to 40. Good morning and welcome to the Walden Gallery.</p>", "start": null}, {"id": "s4-t2", "text": "In today's open lecture, I'm going to be talking about our collection of perfume ornaments, or containers. These beautiful objects now form a significant part of the museum's collection and are very popular with the public. But this has not always been the case.", "html": "<p>In today&#x27;s open lecture, I&#x27;m going to be talking about our collection of perfume ornaments, or containers. These beautiful objects now form a significant part of the museum&#x27;s collection and are very popular with the public. But this has not always been the case.</p>", "start": null}, {"id": "s4-t3", "text": "Up until relatively recently, the large collection of perfume ornaments held in store, donated by Lady Walden at the beginning of the last century, was not considered to be of much interest and was not on show to the general public. Then, as late as 1989, a visiting professor from the Victoria and Albert Museum commented that some of the objects were worth a great deal, and so the display was created, much as you see it here today. Now before I say anything more about the perfume containers, I thought I'd briefly touch on the background to the development of perfumes themselves.", "html": "<p>Up until relatively recently, the large collection of perfume ornaments held in store, donated by Lady Walden at the beginning of the last century, was not considered to be of much interest and was not on show to the general public. Then, as late as 1989, a visiting professor from the Victoria and Albert Museum commented that some of the objects were worth a great deal, and so the display was created, much as you see it here today. Now before I say anything more about the perfume containers, I thought I&#x27;d briefly touch on the background to the development of perfumes themselves.</p>", "start": null}, {"id": "s4-t4", "text": "In the West, perfumery really began as late as the 11th century. Bathing and laundering were considered hazardous undertakings because even though there were ample supplies of water, it was often dirty or even infected. As a consequence, as you can imagine, the air was heavy with unpleasant smells, which had to be countered or covered up.", "html": "<p>In the West, perfumery really began as late as the 11th century. Bathing and laundering were considered hazardous undertakings because even though there were ample supplies of water, it was often dirty or even infected. As a consequence, as you can imagine, the air was heavy with unpleasant smells, which had to be countered or covered up.</p>", "start": null}, {"id": "s4-t5", "text": "In those early days, perfumes were in solid form and mainly made from spices, leaves, and animal fixatives in paste form, for example, musk and ambergris. Wealthy people, the only people who could afford them, carried small globular vessels known as pomanders. I've brought out one ornament from the collection, the oldest one, in fact, from the 14th century, which I'll pass around for you to sample.", "html": "<p>In those early days, perfumes were in solid form and mainly made from spices, leaves, and animal fixatives in paste form, for example, musk and ambergris. Wealthy people, the only people who could afford them, carried small globular vessels known as pomanders. I&#x27;ve brought out one ornament from the collection, the oldest one, in fact, from the 14th century, which I&#x27;ll pass around for you to sample.</p>", "start": null}, {"id": "s4-t6", "text": "These pomanders are solid paste balls made of ambergris impregnated with fragrance. The name was derived from the French for apple of ambergris. They must have had a powerful aroma in those days because even now you can smell the fragrance.", "html": "<p>These pomanders are solid paste balls made of ambergris impregnated with fragrance. The name was derived from the French for apple of ambergris. They must have had a powerful aroma in those days because even now you can smell the fragrance.</p>", "start": null}, {"id": "s4-t7", "text": "Now, during the mediaeval period, basically up until the 16th century, perfumes not only made your surroundings smell sweeter, they were believed to have other special properties. Researchers in the 19th century revealed that in mediaeval times, people thought perfumes could help overcome all kinds of bodily ills. But only recently, researchers at our museum have found that they were also believed to significantly raise the spirits of the wearer.", "html": "<p>Now, during the mediaeval period, basically up until the 16th century, perfumes not only made your surroundings smell sweeter, they were believed to have other special properties. Researchers in the 19th century revealed that in mediaeval times, people thought perfumes could help overcome all kinds of bodily ills. But only recently, researchers at our museum have found that they were also believed to significantly raise the spirits of the wearer.</p>", "start": null}, {"id": "s4-t8", "text": "Turning now to some more technical details, with the advent of liquid perfume from the mid-18th century, craftsmen had to use precision techniques to ensure there was an airtight seal on the container. It is clear that however beautiful these seemingly fragile objects were, they were essentially utilitarian, designed to stop the extremely valuable substances inside them from evaporating. Let's turn now to have a look at some of the key developments in perfume containers in the last 200 years or so.", "html": "<p>Turning now to some more technical details, with the advent of liquid perfume from the mid-18th century, craftsmen had to use precision techniques to ensure there was an airtight seal on the container. It is clear that however beautiful these seemingly fragile objects were, they were essentially utilitarian, designed to stop the extremely valuable substances inside them from evaporating. Let&#x27;s turn now to have a look at some of the key developments in perfume containers in the last 200 years or so.</p>", "start": null}, {"id": "s4-t9", "text": "From the late 18th century onwards, the vinaigrette came into vogue. The vinaigrette was a miniature box which opened on a hinge, containing a tiny sponge soaked with perfume. This was placed under a grill through which you could smell the fragrance.", "html": "<p>From the late 18th century onwards, the vinaigrette came into vogue. The vinaigrette was a miniature box which opened on a hinge, containing a tiny sponge soaked with perfume. This was placed under a grill through which you could smell the fragrance.</p>", "start": null}, {"id": "s4-t10", "text": "It was widely used to carry the highly corrosive scent known as vinegar water, hence the name. The outer box could be made of any material, but the lining was gold because the perfume tended to corrode other substances. From the mid-19th century, vinaigrettes were replaced by more conventional bottles.", "html": "<p>It was widely used to carry the highly corrosive scent known as vinegar water, hence the name. The outer box could be made of any material, but the lining was gold because the perfume tended to corrode other substances. From the mid-19th century, vinaigrettes were replaced by more conventional bottles.</p>", "start": null}, {"id": "s4-t11", "text": "They were often made of glass, of course, but metal was another common material used, and very occasionally they were made of more unusual materials like horn. By now these beautiful objects were more affordable. This was the age of the Industrial Revolution in Western Europe, and the bottles were mass-produced and thus available not just to the very wealthy.", "html": "<p>They were often made of glass, of course, but metal was another common material used, and very occasionally they were made of more unusual materials like horn. By now these beautiful objects were more affordable. This was the age of the Industrial Revolution in Western Europe, and the bottles were mass-produced and thus available not just to the very wealthy.</p>", "start": null}, {"id": "s4-t12", "text": "In the last quarter of the 19th century, one company above all became associated with the design and production of perfume bottles, the Tiffany Company. They developed a wide range of designs, most notably based on those of the furniture of the period. Their particular achievement was their stylish and clever working of crystal.", "html": "<p>In the last quarter of the 19th century, one company above all became associated with the design and production of perfume bottles, the Tiffany Company. They developed a wide range of designs, most notably based on those of the furniture of the period. Their particular achievement was their stylish and clever working of crystal.</p>", "start": null}, {"id": "s4-t13", "text": "Although these perfume ornaments were very expensive, Tiffany & Co. were able to use catalogues to reach a wider clientele. Many innovative designs were used in perfume ornaments produced in the 1920s and 30s.", "html": "<p>Although these perfume ornaments were very expensive, Tiffany &amp; Co. were able to use catalogues to reach a wider clientele. Many innovative designs were used in perfume ornaments produced in the 1920s and 30s.</p>", "start": null}, {"id": "s4-t14", "text": "The most notable was probably the vanity. This was an ingeniously designed case used not only for holding perfume, but also makeup, in a whole maze of tiny additional compartments. It was made in the first instance of ivory, but later bakelite was used, the resinous plastic which was so popular with all kinds of designers of the period.", "html": "<p>The most notable was probably the vanity. This was an ingeniously designed case used not only for holding perfume, but also makeup, in a whole maze of tiny additional compartments. It was made in the first instance of ivory, but later bakelite was used, the resinous plastic which was so popular with all kinds of designers of the period.</p>", "start": null}, {"id": "s4-t15", "text": "Now, I've brought along a selection of the items in the collection which I've set out here. If you'd like to come and gather... That is the end of Section 4. You now have half a minute to check your answers. That is the end of the listening test.", "html": "<p>Now, I&#x27;ve brought along a selection of the items in the collection which I&#x27;ve set out here. If you&#x27;d like to come and gather... That is the end of Section 4. You now have half a minute to check your answers. That is the end of the listening test.</p>", "start": null}, {"id": "s4-t16", "text": "You now have 10 minutes to transfer your answers to the listening answer sheet.", "html": "<p>You now have 10 minutes to transfer your answers to the listening answer sheet.</p>", "start": null}]}, "transcripts": {"1": "<p>You will hear a telephone conversation between a man who wants to rent an apartment and an agent at a property rental service. First, you have some time to look at questions 1 to 5. Now listen carefully and answer questions 1 to 5. Good morning, AA Property. Can I help you? Yes, good morning.</p><p>I&#x27;m looking for an apartment to rent. OK. Is that here in Birmingham? That&#x27;s right.</p><p>Right. I&#x27;ll just take some personal details if I may. So, if I can just take your name? Kevin Walker.</p><p>Right. And can I have your present address, please? Well, we&#x27;re staying with friends at present, so the address is 354 Forest Road. Is that Forest with one R? That&#x27;s right.</p><p>And that&#x27;s in West Bromwich. I&#x27;m afraid I don&#x27;t know the postcode. That&#x27;s OK.</p><p>And a contact phone number? 07817983602. Lovely. And if I could just ask your occupation? Certainly.</p><p>I&#x27;m a dentist and my wife&#x27;s a teacher, but she&#x27;s at home at present looking after the children. OK. So, I&#x27;ll just put your occupation.</p><p>Right. Well, now I&#x27;ll take some details about the kind of property you&#x27;re looking for. You said you&#x27;re looking for an apartment, is that right? Yeah.</p><p>OK. So, how many bedrooms do you want? Two. And did you want it furnished? No, unfurnished.</p><p>Right. Well, that gives you quite a bit more choice, so that&#x27;s good. And what&#x27;s the maximum rent you&#x27;d be prepared to pay? Well, we&#x27;d like to stay under £600 if possible, but we could go up to £650 for the right place.</p><p>Right. So, do you have any other definite requirements? Well, coming back to the bedrooms, they have to be doubles, both of them. OK.</p><p>I&#x27;ll make a note of that. Before you hear the rest of the conversation, you have some time to look at questions 6 to 10. Now listen and answer questions 6 to 10.</p><p>So, are you looking for something straight away? I assume you are if you&#x27;re staying with friends. Well, as soon as possible, yes. Well, it&#x27;s October 17th today, so we&#x27;re probably looking at November 1st at the earliest.</p><p>Would that be OK? Well, I&#x27;d have preferred something in October, but OK, let&#x27;s put that date down for now. Fine. Now, is there anything else you&#x27;d like? Well, our last flat had a garage, but actually, we never used it, so I&#x27;m not really worried about that.</p><p>But we&#x27;d like a balcony if possible. It&#x27;s nice not to be too shut in. Yes.</p><p>You&#x27;ll find most modern apartments do have one. It&#x27;s only the converted properties that don&#x27;t. But of course, if you&#x27;re in an older property, you might have use of a garden.</p><p>Would that be a possible alternative? Oh yes, either of those would be good. What about transport? Would you want off-street parking? No, parking doesn&#x27;t matter, but it&#x27;d be good to have somewhere not too far from a station if possible. But it&#x27;s not essential.</p><p>I&#x27;ve got a bike. Right. And what else? You&#x27;ll want a lounge, and will you want a separate dining room? Well, not really.</p><p>We tend to eat in the kitchen, so it&#x27;d be good if that was large enough for us to do that. That might be difficult, but I&#x27;ll make a note of it anyway. Right, well, let&#x27;s have a look at what...</p>", "2": "<p>Section 2. You will hear a local councillor giving advice on the radio about cleaning up after recent bad weather.</p><p>First, you have some time to look at questions 11 to 16 on page 3. Now listen carefully and answer questions 11 to 16. Welcome to Radio OK, your community radio station. After our recent bad storm, we have Councillor Phil Evans joining us to tell us about the clean-up effort.</p><p>Welcome, Phil. Hello. Thanks for having me.</p><p>Well, we had some pretty severe weather at the weekend. Thankfully, it wasn&#x27;t quite as bad as last year&#x27;s storm. Although there was some damage to trees, it was definitely not on the same scale as last year, and we were expecting the river level to rise higher than it did.</p><p>But having said that, a much larger number of homes have been damaged this year due to flash flooding near the creek. Those of you who have experienced flooding, we ask you to be especially careful. I know it&#x27;s upsetting to see your home full of water, but please be patient, as there&#x27;s nothing you can do until the river level drops, hopefully in two or three days.</p><p>You won&#x27;t have any electricity at the moment, but we are working as fast as we can to get it reconnected. When it comes to cleaning up your garden, you might be tempted to just throw dead branches and so on into your normal garbage bin. Please don&#x27;t.</p><p>We&#x27;re asking people to simply stack them outside on the footpath ready for Council collection. We plan to cut them up and use them for composting. For those of you who don&#x27;t have cooking facilities at the moment, I&#x27;m afraid we won&#x27;t be able to deliver hot meals to your home like the community centre did last year.</p><p>Instead, we&#x27;ll be issuing vouchers that you can use to get food from any of the nominated restaurants. Just come to the Council office to collect them. We&#x27;ve had an overwhelming number of people offering to help out.</p><p>Anyone who would like to volunteer, please don&#x27;t call the Council office directly. Instead, if you&#x27;re available to help clean up, just turn up at the community centre by 8am tomorrow and you&#x27;ll be given the necessary tools and assigned a task by the Council Work Supervisor. As the water level goes down, we may discover more problems.</p><p>We&#x27;ll be assessing the drinking water regularly so that there&#x27;s no risk of contamination. Just be aware that local wildlife can be forced out of their natural habitat in this weather. Let the Council know of any unusual sightings so we can safely relocate them.</p><p>It may seem that mosquitoes are around in abundance right now, but the actual population is usual for this time of year. Before you hear the rest of the talk, you have some time to look at questions 17 to 20 on page 4. Now listen and answer questions 17 to 20. Now we&#x27;ll give you some information about key areas in the town.</p><p>The school escaped any real problems and we&#x27;ll be using its car park and some of the classrooms to coordinate the clean up. Because of that, the Principal is asking for volunteers to assist in getting the classrooms set back up again with the desks back in their proper places before the new term begins after the holidays. The hospital is still fully functional and the only damage there was to the canteen where a tree branch broke a window.</p><p>You can still access the area as normal, we just ask that you park at the rear of the hospital until the repair work has been completed. If you need to get to the shops, the High Street is still a little flooded so I&#x27;m afraid you&#x27;ll have to collect your shopping on foot for a little while. Hopefully, it won&#x27;t be long before you&#x27;ll be able to drive there again.</p><p>Before the storm, we had hoped to begin work on modernising the bikeway that runs along the river. We were particularly looking forward to having bike storage facilities installed. While the bikeway itself is okay, unfortunately the area around it is covered in water.</p><p>So we&#x27;ve postponed our work there indefinitely and I&#x27;m afraid it&#x27;s now unlikely that this will ever go ahead. Well, that&#x27;s everything for now. I&#x27;ll be back with a further update tomorrow.</p><p>That is the end of Section 2. You now have half a minute to check your answers.</p>", "3": "<p>Now turn to Section 3 on page 5. Section 3. You will hear a student talking to a tutor at her college about the possibility of changing her course. First, you have some time to look at questions 21 to 24 on page 5. Now listen carefully and answer questions 21 to 24.</p><p>Ah, hello. Do come in. Thanks.</p><p>I understand you wanted to see me about changing courses? Yes, that&#x27;s right. Well, that&#x27;s fine. Do sit down.</p><p>Oh, thank you. Now, you&#x27;re Sally Lehman? That&#x27;s it. Right then, Sally.</p><p>And what course are you doing at the present? It&#x27;s Economic History. Uh-huh. And when did you start? Last September.</p><p>Right, good. Now, of course, we&#x27;ll have the chance to talk through any problems you&#x27;ve been having in a moment, but let me just make a note of what courses you might be interested in changing to. Well, there are several that I&#x27;ve thought about, but what I&#x27;d like to do most is politics.</p><p>Well, that is a very popular course. I know, and there might not be places, but… Sure, I&#x27;ll certainly take a note of that. But what about another option? Well, I had thought of changing course completely and trying business studies, but then I realised it wasn&#x27;t really me, so I thought of philosophy.</p><p>Before you hear the rest of the discussion, you have some time to look at questions 25 to 30 on page 5. Now listen and answer questions 25 to 30. Right, well, that&#x27;s useful to know, but if at all possible, it is good to talk through the problems you are having at the moment and see if there&#x27;s any way we can help or that you can help yourself. After all, with all the effort that you&#x27;ve put in already, it would be a pity to have to start all over again.</p><p>Oh no, I realise that. And actually, I would like to have a go at staying with Economic History. Good.</p><p>Yeah, well, let&#x27;s see. Let&#x27;s talk through some of the problems you&#x27;ve been having. What would you say was your major difficulty on the course? I think I&#x27;d have to say the worst thing is that I find the lectures difficult.</p><p>Aha. And how have you tried to overcome this? Well, I did try recording lectures, you know. Yes, that&#x27;s a good idea.</p><p>And did you find it helped? To a certain extent, but... Well, I would certainly continue with that strategy, but you might also like to try getting together with other fellow students to discuss lectures in what we call a discussion group. Yeah, I&#x27;ve heard of some of my course mates doing that. I could certainly ask if I could join.</p><p>Good. I&#x27;m sure you&#x27;d find it a help. And any other problems? Well, this really worried me at the beginning.</p><p>The fact that there are not enough tutorials. Not enough tutorials. Did you talk to your tutor about it? Yeah, that was what I thought was the best strategy.</p><p>It&#x27;s what all the student handbooks say. Yeah, and what was the outcome? Well, really, just that she&#x27;s very busy and I have to fit in tutorials when she&#x27;s available, which is really difficult. I agree.</p><p>It must seem that way. Why don&#x27;t you try arranging meetings in advance? Well, I can certainly give it a go. Yeah.</p><p>But I suppose the thing that&#x27;s been really upsetting me recently is my bad assignment grade. How many have you had back? Just the one. Well, you could say it was early days yet.</p><p>Well, for the last assignment, which we&#x27;ve just handed in, I did more background reading. And did you feel that helped? Oh, yes, I think so. Well, another strategy might be visiting student services.</p><p>They offer a lot of advice on assignment preparation. Well, I didn&#x27;t want to bother them. That&#x27;s their job.</p><p>It&#x27;d be well worth trying. OK, I&#x27;ll certainly look into that. Now, what I&#x27;ve done here is to keep a record of our discussions and suggested strategies.</p><p>And what we normally do is to ask you to try out our suggestions for a while and then come back to discuss the situation, see whether it&#x27;s improved. And if not, then we can start thinking seriously about those alternative courses. So you&#x27;d like me to come back? Yes.</p><p>Let&#x27;s say in a month&#x27;s time. OK. That&#x27;d be on 17th of February at 3.30. Is that all right? Yeah, sure.</p><p>And will I meet with you? I&#x27;m afraid I&#x27;ll be on leave at that time. But I&#x27;ll leave this record on file and you&#x27;ll be meeting our senior advisor. Senior advisor.</p><p>OK, fine. Lovely. Well, I do hope things improve, Sally, and that the change won&#x27;t be necessary.</p><p>And if it is, well, we can think about that later. OK? OK. Thanks very much.</p><p>Pleasure. Good luck. That is the end of Section 3. You now have half a minute to check your answers.</p>", "4": "<p>Now turn to Section 4 on page 6. Section 4. You will hear a museum curator giving a presentation about her museum&#x27;s collection of perfume containers, also known as perfume ornaments. First, you have some time to look at questions 31 to 40 on pages 6 and 7. Now listen carefully and answer questions 31 to 40. Good morning and welcome to the Walden Gallery.</p><p>In today&#x27;s open lecture, I&#x27;m going to be talking about our collection of perfume ornaments, or containers. These beautiful objects now form a significant part of the museum&#x27;s collection and are very popular with the public. But this has not always been the case.</p><p>Up until relatively recently, the large collection of perfume ornaments held in store, donated by Lady Walden at the beginning of the last century, was not considered to be of much interest and was not on show to the general public. Then, as late as 1989, a visiting professor from the Victoria and Albert Museum commented that some of the objects were worth a great deal, and so the display was created, much as you see it here today. Now before I say anything more about the perfume containers, I thought I&#x27;d briefly touch on the background to the development of perfumes themselves.</p><p>In the West, perfumery really began as late as the 11th century. Bathing and laundering were considered hazardous undertakings because even though there were ample supplies of water, it was often dirty or even infected. As a consequence, as you can imagine, the air was heavy with unpleasant smells, which had to be countered or covered up.</p><p>In those early days, perfumes were in solid form and mainly made from spices, leaves, and animal fixatives in paste form, for example, musk and ambergris. Wealthy people, the only people who could afford them, carried small globular vessels known as pomanders. I&#x27;ve brought out one ornament from the collection, the oldest one, in fact, from the 14th century, which I&#x27;ll pass around for you to sample.</p><p>These pomanders are solid paste balls made of ambergris impregnated with fragrance. The name was derived from the French for apple of ambergris. They must have had a powerful aroma in those days because even now you can smell the fragrance.</p><p>Now, during the mediaeval period, basically up until the 16th century, perfumes not only made your surroundings smell sweeter, they were believed to have other special properties. Researchers in the 19th century revealed that in mediaeval times, people thought perfumes could help overcome all kinds of bodily ills. But only recently, researchers at our museum have found that they were also believed to significantly raise the spirits of the wearer.</p><p>Turning now to some more technical details, with the advent of liquid perfume from the mid-18th century, craftsmen had to use precision techniques to ensure there was an airtight seal on the container. It is clear that however beautiful these seemingly fragile objects were, they were essentially utilitarian, designed to stop the extremely valuable substances inside them from evaporating. Let&#x27;s turn now to have a look at some of the key developments in perfume containers in the last 200 years or so.</p><p>From the late 18th century onwards, the vinaigrette came into vogue. The vinaigrette was a miniature box which opened on a hinge, containing a tiny sponge soaked with perfume. This was placed under a grill through which you could smell the fragrance.</p><p>It was widely used to carry the highly corrosive scent known as vinegar water, hence the name. The outer box could be made of any material, but the lining was gold because the perfume tended to corrode other substances. From the mid-19th century, vinaigrettes were replaced by more conventional bottles.</p><p>They were often made of glass, of course, but metal was another common material used, and very occasionally they were made of more unusual materials like horn. By now these beautiful objects were more affordable. This was the age of the Industrial Revolution in Western Europe, and the bottles were mass-produced and thus available not just to the very wealthy.</p><p>In the last quarter of the 19th century, one company above all became associated with the design and production of perfume bottles, the Tiffany Company. They developed a wide range of designs, most notably based on those of the furniture of the period. Their particular achievement was their stylish and clever working of crystal.</p><p>Although these perfume ornaments were very expensive, Tiffany &amp; Co. were able to use catalogues to reach a wider clientele. Many innovative designs were used in perfume ornaments produced in the 1920s and 30s.</p><p>The most notable was probably the vanity. This was an ingeniously designed case used not only for holding perfume, but also makeup, in a whole maze of tiny additional compartments. It was made in the first instance of ivory, but later bakelite was used, the resinous plastic which was so popular with all kinds of designers of the period.</p><p>Now, I&#x27;ve brought along a selection of the items in the collection which I&#x27;ve set out here. If you&#x27;d like to come and gather... That is the end of Section 4. You now have half a minute to check your answers. That is the end of the listening test.</p><p>You now have 10 minutes to transfer your answers to the listening answer sheet.</p>"}, "questionSegments": {"1": ["s1-t4"], "2": ["s1-t6"], "3": ["s1-t7"], "4": ["s1-t9"], "5": ["s1-t11"], "6": ["s1-t13"], "7": ["s1-t15"], "8": ["s1-t16"], "9": ["s1-t17"], "10": ["s1-t19"], "11": ["s2-t5"], "12": ["s2-t5"], "13": ["s2-t7"], "14": ["s2-t8"], "15": ["s2-t9"], "16": ["s2-t10"], "17": ["s2-t12"], "18": ["s2-t12"], "19": ["s2-t13"], "20": ["s2-t15"], "21": ["s3-t5"], "22": ["s3-t5"], "23": ["s3-t6"], "24": ["s3-t7"], "25": ["s3-t10"], "26": ["s3-t12"], "27": ["s3-t14"], "28": ["s3-t18"], "29": ["s3-t22"], "30": ["s3-t23"], "31": ["s4-t3"], "32": ["s4-t4"], "33": ["s4-t6"], "34": ["s4-t7"], "35": ["s4-t8"], "36": ["s4-t9"], "37": ["s4-t10"], "38": ["s4-t11"], "39": ["s4-t12"], "40": ["s4-t14"]}, "evidenceCues": {"11": "a much larger number of homes have been damaged", "12": "please be patient", "13": "simply stack them outside on the footpath", "14": "we'll be issuing vouchers", "15": "just turn up at the community centre by 8am", "16": "Let the Council know of any unusual sightings", "17": "the Principal is asking for volunteers", "18": "the only damage there was to the canteen", "19": "you'll have to collect your shopping on foot", "20": "we've postponed our work there indefinitely", "21": "It's Economic History", "31": "a visiting professor from the Victoria and Albert Museum", "32": "Bathing and laundering were considered hazardous", "33": "The name was derived from the French", "34": "significantly raise the spirits of the wearer", "35": "stop the extremely valuable substances inside them from evaporating", "36": "a tiny sponge soaked with perfume", "37": "but the lining was gold", "38": "the bottles were mass-produced", "39": "stylish and clever working of crystal", "40": "used not only for holding perfume, but also makeup"}, "headingsBySection": {}, "grading": {"pairs": [], "sets": []}, "groups": [[1, 10], [11, 20], [21, 30], [31, 40]], "questionTypes": {"1": "gap", "2": "gap", "3": "gap", "4": "gap", "5": "gap", "6": "gap", "7": "gap", "8": "gap", "9": "gap", "10": "gap", "11": "single", "12": "single", "13": "single", "14": "single", "15": "single", "16": "single", "17": "matching", "18": "matching", "19": "matching", "20": "matching", "21": "gap", "22": "gap", "23": "gap", "24": "gap", "25": "gap", "26": "gap", "27": "gap", "28": "gap", "29": "gap", "30": "gap", "31": "single", "32": "single", "33": "single", "34": "single", "35": "single", "36": "single", "37": "single", "38": "single", "39": "single", "40": "single"}, "audioFiles": {"1": "4-1.mp3", "2": "4-2.mp3", "3": "4-3.mp3", "4": "4-4.mp3"}, "audio": {"1": "Listening - Vol 8/Test 4/audio/part-1.mp3", "2": "Listening - Vol 8/Test 4/audio/part-2.mp3", "3": "Listening - Vol 8/Test 4/audio/part-3.mp3", "4": "Listening - Vol 8/Test 4/audio/part-4.mp3"}, "sourceAnswerKey": {"1": ["354 Forest"], "2": ["07817983602"], "3": ["dentist"], "4": ["unfurnished"], "5": ["doubles"], "6": ["1 November", "1st November", "November 1", "November 1st"], "7": ["balcony"], "8": ["garden"], "9": ["station"], "10": ["kitchen"], "11": ["A"], "12": ["C"], "13": ["C"], "14": ["A"], "15": ["B"], "16": ["B"], "17": ["D"], "18": ["F"], "19": ["A"], "20": ["C"], "21": ["Economic History"], "22": ["last September"], "23": ["Politics"], "24": ["Philosophy"], "25": ["lectures difficult"], "26": ["discussion group"], "27": ["not enough tutorials"], "28": ["student services"], "29": ["17th of February", "17 February", "February 17", "17th February"], "30": ["senior advisor"], "31": ["C"], "32": ["A"], "33": ["A"], "34": ["C"], "35": ["B"], "36": ["B"], "37": ["A"], "38": ["B"], "39": ["C"], "40": ["A"]}, "sourceNotes": [], "hasAnswerKey": true};
